<?php
namespace App\Http\Controllers\Api\Admin;use App\Http\Controllers\Controller;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class MarketingController extends Controller{public function dashboard(Request$r):JsonResponse{$this->view($r);$q=$this->query($r);return response()->json(['data'=>$this->aggregate($q)]);}public function index(Request$r):JsonResponse{$this->view($r);$r->validate(['sort'=>['nullable',Rule::in(['created_at','name','code','status','starts_at','ends_at','budget','spend'])],'direction'=>['nullable',Rule::in(['asc','desc'])],'per_page'=>['nullable','integer','between:1,100']]);$q=$this->query($r);$rows=(clone$q)->leftJoin('users as u','u.id','=','mc.owner_id')->select('mc.*','u.name as owner_name')->orderBy('mc.'.($r->sort??'created_at'),$r->direction??'desc')->paginate($r->integer('per_page',25));$ids=collect($rows->items())->pluck('id');$channels=DB::table('marketing_campaign_channels')->whereIn('campaign_id',$ids)->get()->groupBy('campaign_id');foreach($rows->items()as$row)$row->channels=($channels[$row->id]??collect())->pluck('channel')->values();return response()->json(['data'=>['campaigns'=>$rows,'summary'=>$this->aggregate($q)]]);}public function show(Request$r,string$id):JsonResponse{$this->view($r);$row=$this->find($id);abort_unless($row,404);return response()->json(['data'=>['campaign'=>$row,'channels'=>DB::table('marketing_campaign_channels')->where('campaign_id',$row->id)->pluck('channel'),'approvals'=>DB::table('marketing_campaign_approvals')->where('campaign_id',$row->id)->latest()->get(),'exceptions'=>DB::table('marketing_campaign_exceptions')->where('campaign_id',$row->id)->latest()->get(),'activity'=>DB::table('activity_log')->where('subject_id',$row->id)->where('description','like','marketing_campaign.%')->latest()->get()]]);}public function store(Request$r):JsonResponse{$this->permit($r,'marketing.create');return$this->save($r);}public function update(Request$r,string$id):JsonResponse{$this->permit($r,'marketing.update');$row=$this->find($id);abort_unless($row,404);return$this->save($r,$row->id);}public function transition(Request$r,string$id):JsonResponse{$this->permit($r,'marketing.update');$row=$this->find($id);abort_unless($row,404);$d=$r->validate(['action'=>['required',Rule::in(['activate','pause','resume','schedule','cancel','archive','request_approval','approve','reject'])],'reason'=>['nullable','string','max:2000']]);$map=['activate'=>'active','pause'=>'paused','resume'=>'active','schedule'=>'scheduled','cancel'=>'cancelled','archive'=>'archived'];if(in_array($d['action'],['approve','reject','request_approval'])){$this->permit($r,$d['action']==='request_approval'?'marketing.update':'marketing.approve');$approval=$d['action']==='request_approval'?'pending':($d['action']==='approve'?'approved':'rejected');DB::table('marketing_campaigns')->where('id',$row->id)->update(['approval_status'=>$approval,'updated_at'=>now()]);DB::table('marketing_campaign_approvals')->insert(['campaign_id'=>$row->id,'submitted_by'=>$r->user()->id,'reviewed_by'=>$d['action']==='request_approval'?null:$r->user()->id,'status'=>$approval,'comments'=>$d['reason']??null,'submitted_at'=>now(),'reviewed_at'=>$d['action']==='request_approval'?null:now(),'created_at'=>now(),'updated_at'=>now()]);}else{if($d['action']==='activate')abort_if($row->approval_status!=='approved'||$row->budget<=0||blank($row->starts_at),422,'Campaign must be approved with budget and start date before activation.');DB::table('marketing_campaigns')->where('id',$row->id)->update(['status'=>$map[$d['action']],'updated_at'=>now()]);}activity('admin')->causedBy($r->user())->withProperties(['campaign_id'=>$row->id,'action'=>$d['action']])->log('marketing_campaign.status_changed');return response()->json(['data'=>['campaign'=>$this->find((string)$row->id)]]);}public function bulk(Request$r):JsonResponse{$this->permit($r,'marketing.update');$d=$r->validate(['ids'=>['required','array','min:1','max:100'],'ids.*'=>['integer','exists:marketing_campaigns,id'],'action'=>['required',Rule::in(['pause','archive','request_approval'])]]);DB::transaction(function()use($r,$d){foreach($d['ids']as$id){$row=$this->find((string)$id);if($d['action']==='request_approval')DB::table('marketing_campaigns')->where('id',$id)->update(['approval_status'=>'pending','updated_at'=>now()]);else DB::table('marketing_campaigns')->where('id',$id)->update(['status'=>$d['action']==='pause'?'paused':'archived','updated_at'=>now()]);activity('admin')->causedBy($r->user())->withProperties(['campaign_id'=>$id,'action'=>$d['action']])->log('marketing_campaign.bulk_status_changed');}});return response()->json(['data'=>['updated'=>count($d['ids'])]]);}private function save(Request$r,?int$id=null):JsonResponse{$d=$r->validate(['name'=>[$id?'sometimes':'required','string','max:180'],'description'=>['nullable','string','max:4000'],'campaign_type'=>[$id?'sometimes':'required','string','max:60'],'owner_id'=>['nullable','integer','exists:users,id'],'business_unit'=>['nullable','string','max:80'],'audience_name'=>['nullable','string','max:150'],'audience_size'=>['nullable','integer','min:0'],'currency'=>['nullable','string','size:3'],'budget'=>['nullable','numeric','min:0'],'starts_at'=>['nullable','date'],'ends_at'=>['nullable','date','after_or_equal:starts_at'],'channels'=>['nullable','array'],'channels.*'=>['string','max:50']]);$creating=$id===null;$id=DB::transaction(function()use($r,$d,$id,$creating){$channels=$d['channels']??null;unset($d['channels']);$d['updated_by']=$r->user()->id;$d['updated_at']=now();if($creating){$d['uuid']=(string)Str::uuid();$d['code']='MKT-'.now()->format('Y').'-'.str_pad((string)((DB::table('marketing_campaigns')->max('id')??0)+1),5,'0',STR_PAD_LEFT);$d['created_by']=$r->user()->id;$d['created_at']=now();$id=DB::table('marketing_campaigns')->insertGetId($d);}else DB::table('marketing_campaigns')->where('id',$id)->update($d);if($channels!==null){DB::table('marketing_campaign_channels')->where('campaign_id',$id)->delete();foreach(array_unique($channels)as$c)DB::table('marketing_campaign_channels')->insert(['campaign_id'=>$id,'channel'=>$c,'created_at'=>now(),'updated_at'=>now()]);}activity('admin')->causedBy($r->user())->withProperties(['campaign_id'=>$id,'fields'=>array_keys($d)])->log($creating?'marketing_campaign.created':'marketing_campaign.updated');return$id;});return response()->json(['data'=>['campaign'=>$this->find((string)$id)]],$creating?201:200);}private function query(Request$r){$q=DB::table('marketing_campaigns as mc')->whereNull('mc.deleted_at');foreach(['status','campaign_type','owner_id','approval_status','business_unit']as$k)if($r->filled($k)&&$r->$k!=='All')$q->where('mc.'.$k,$r->$k);if($r->filled('channel')&&$r->channel!=='All')$q->whereExists(fn($x)=>$x->selectRaw('1')->from('marketing_campaign_channels as cc')->whereColumn('cc.campaign_id','mc.id')->where('cc.channel',$r->channel));if($r->filled('search')){$s='%'.$r->search.'%';$q->where(fn($x)=>$x->where('mc.name','like',$s)->orWhere('mc.code','like',$s)->orWhere('mc.audience_name','like',$s));}return$q;}private function aggregate($q){$total=(clone$q)->count();$spend=(float)(clone$q)->sum('mc.spend');$rev=(float)(clone$q)->sum('mc.attributed_revenue');$counts=(clone$q)->selectRaw('mc.status,count(*) count')->groupBy('mc.status')->pluck('count','status');$channels=DB::table('marketing_campaign_channels')->joinSub((clone$q)->select('mc.id'),'filtered','filtered.id','=','marketing_campaign_channels.campaign_id')->selectRaw('channel,count(*) count')->groupBy('channel')->get();$activity=DB::table('activity_log')->leftJoin('users','users.id','=','activity_log.causer_id')->where('description','like','marketing_campaign.%')->latest('activity_log.created_at')->limit(10)->get(['activity_log.id','activity_log.description','activity_log.created_at','users.name as actor']);return['updated_at'=>now()->toIso8601String(),'metrics'=>['total'=>$total,'active'=>(int)($counts['active']??0),'scheduled'=>(int)($counts['scheduled']??0),'awaiting_approval'=>(clone$q)->where('mc.approval_status','pending')->count(),'paused'=>(int)($counts['paused']??0),'completed'=>(int)($counts['completed']??0),'budget'=>(float)(clone$q)->sum('mc.budget'),'spend'=>$spend,'revenue'=>$rev,'roas'=>$spend>0?$rev/$spend:0,'reach'=>(int)(clone$q)->sum('mc.reach'),'conversions'=>(int)(clone$q)->sum('mc.conversions')],'status_counts'=>$counts,'channels'=>$channels,'exceptions'=>DB::table('marketing_campaign_exceptions')->joinSub((clone$q)->select('mc.id'),'filtered','filtered.id','=','marketing_campaign_exceptions.campaign_id')->where('marketing_campaign_exceptions.status','open')->get(),'activity'=>$activity,'performance'=>[],'audience'=>['marketable'=>DB::table('customer_consents')->where('consent_type','marketing')->where('is_granted',true)->count()]];}private function find($id){return DB::table('marketing_campaigns as mc')->leftJoin('users as u','u.id','=','mc.owner_id')->whereNull('mc.deleted_at')->where(fn($q)=>$q->where('mc.code',$id)->orWhere('mc.uuid',$id)->when(ctype_digit($id),fn($x)=>$x->orWhere('mc.id',(int)$id)))->select('mc.*','u.name as owner_name')->first();}private function view($r){$this->permit($r,'marketing.view');}private function permit($r,$p){abort_unless($r->user()->hasPermission($p)||$r->user()->hasPermission('admin.dashboard.view'),403);}}
